mapper.select:
SELECT COALESCE(MAX(snapshot_no), 0) + 1
FROM proj_project_stage_snapshot
WHERE tenant_id = #{query.tenantId}
  AND project_id = #{query.projectId}
  AND stage_code = #{query.stageCode}
  AND deleted = b'0'

